"""Ledgerly agent: tool loop + human approval gate + overdue reminders.

Safety model
------------
* The planner (an LLM, or the deterministic `RulePlanner`) can only call the tools in
  `Agent.TOOLS`: create_invoice, get_status, send_reminder, list_overdue.
  None of them move money or send email. Outgoing actions are *queued* as
  `PendingAction`s.
* `approve(action_id)` is NOT a tool. Only the human-facing surface (CLI / UI / test)
  calls it.
* Defence in depth: the PayPal client is wrapped in `GatedClient`, which raises
  `ApprovalRequired` for send / remind / record-payment unless `approve()` has opened a
  one-shot permit for that exact (operation, invoice_id). So even a buggy tool or a
  prompt-injected planner cannot send.
"""
from __future__ import annotations

import contextlib
import copy
import hashlib
import json
import uuid
from dataclasses import dataclass, field
from datetime import date, datetime, timezone
from decimal import Decimal
from typing import Any, Callable, Optional, Protocol

from .extract import Extraction, Extractor, RulesExtractor, quantize, split_by_currency, validate
from .paypal import (
    OPEN_STATUSES, PAID_STATUSES, STATUSES, InvoicingClient, PayPalError, Response, WebhookError,
    build_invoice, parse_webhook_event,
)

GATED_OPS = {"send_invoice", "remind_invoice", "record_payment"}


class ApprovalRequired(PermissionError):
    pass


class GatedClient:
    """Wraps an InvoicingClient; outgoing operations need a one-shot permit."""

    def __init__(self, inner: InvoicingClient):
        self._inner = inner
        self._permits: set[tuple[str, str]] = set()
        self.blocked: list[tuple[str, str]] = []

    @contextlib.contextmanager
    def permit(self, op: str, invoice_id: str):
        key = (op, invoice_id)
        self._permits.add(key)
        try:
            yield
        finally:
            self._permits.discard(key)

    def _check(self, op: str, invoice_id: str) -> None:
        if (op, invoice_id) not in self._permits:
            self.blocked.append((op, invoice_id))
            raise ApprovalRequired(f"{op}({invoice_id}) requires human approval")

    def send_invoice(self, invoice_id: str, body: Optional[dict] = None) -> Response:
        self._check("send_invoice", invoice_id)
        return self._inner.send_invoice(invoice_id, body)

    def remind_invoice(self, invoice_id: str, body: Optional[dict] = None) -> Response:
        self._check("remind_invoice", invoice_id)
        return self._inner.remind_invoice(invoice_id, body)

    def record_payment(self, invoice_id: str, body: dict) -> Response:
        self._check("record_payment", invoice_id)
        return self._inner.record_payment(invoice_id, body)

    def __getattr__(self, name: str) -> Any:  # read-only / draft calls pass through
        return getattr(self._inner, name)


@dataclass
class PendingAction:
    id: str
    kind: str  # send_invoice | send_reminder
    invoice_id: str
    summary: str
    payload: dict
    status: str = "PENDING"  # PENDING | APPROVED | REJECTED | FAILED
    result: Any = None
    created_at: str = field(default_factory=lambda: datetime.now(timezone.utc).isoformat())

    def to_dict(self) -> dict:
        # A displayed review must not be an alias into the queued action.
        return copy.deepcopy({k: getattr(self, k) for k in
                              ("id", "kind", "invoice_id", "summary", "payload", "status", "result", "created_at")})


@dataclass
class LedgerEntry:
    invoice_id: str
    invoice_number: str
    client_name: Optional[str]
    client_email: str
    currency: str
    total: Decimal
    due_days: Optional[int]
    status: str = "DRAFT"
    sent_on: Optional[date] = None
    paid_amount: Decimal = Decimal(0)
    reminders_sent: int = 0
    last_reminder_on: Optional[date] = None
    prepaid: Decimal = Decimal(0)
    provider_due_on: Optional[date] = None
    provider_due_known: bool = False
    invoice_due_on: Optional[date] = None
    provider_receipt_pending: bool = False

    @property
    def due_on(self) -> Optional[date]:
        if self.provider_due_known:
            return self.provider_due_on
        if self.provider_receipt_pending:
            # An observed draft receipt term supersedes earlier positive terms.
            return None if self.status == "DRAFT" else self.sent_on
        if self.sent_on is None or self.due_days is None:
            return None
        # Positive terms retain the draft deadline; approval does not restart them.
        if self.due_days > 0 and self.invoice_due_on is not None:
            return self.invoice_due_on
        return date.fromordinal(self.sent_on.toordinal() + self.due_days)

    @property
    def balance(self) -> Decimal:
        return max(self.total - self.paid_amount, Decimal(0))

    def days_overdue(self, today: date) -> int:
        d = self.due_on
        return 0 if d is None else max((today - d).days, 0)

    def to_dict(self) -> dict:
        return {
            "invoice_id": self.invoice_id, "invoice_number": self.invoice_number,
            "client_name": self.client_name, "client_email": self.client_email,
            "currency": self.currency, "total": str(self.total), "paid_amount": str(self.paid_amount),
            "balance": str(self.balance), "status": self.status,
            "sent_on": self.sent_on.isoformat() if self.sent_on else None,
            "due_on": self.due_on.isoformat() if self.due_on else None,
            "reminders_sent": self.reminders_sent,
        }


# ------------------------------------------------------------ reminder drafting

class ReminderDrafter(Protocol):
    def draft(self, entry: LedgerEntry, today: date, freelancer: str) -> dict: ...


class TemplateReminderDrafter:
    """Deterministic, tone escalates with lateness. Swap for an LLM drafter if you like;
    the agent still queues the result for approval either way."""

    def draft(self, entry: LedgerEntry, today: date, freelancer: str) -> dict:
        late = entry.days_overdue(today)
        first = (entry.client_name or "there").split()[0]
        amt = f"{entry.currency} {entry.balance:,}"
        partial = (f" Thank you for the {entry.currency} {entry.paid_amount:,} received so far;"
                   f" the remaining balance is {amt}.") if entry.paid_amount > 0 else ""
        if late <= 7:
            tone, subject = "friendly", f"Friendly reminder: invoice {entry.invoice_number}"
            body = (f"Hi {first},\n\nJust a quick nudge that invoice {entry.invoice_number} for {amt} "
                    f"was due on {entry.due_on:%b %d, %Y}.{partial} You can pay securely via the PayPal link "
                    f"in the original invoice email.\n\nThanks so much,\n{freelancer}")
        elif late <= 30:
            tone, subject = "firm", f"Invoice {entry.invoice_number} is {late} days overdue"
            body = (f"Hi {first},\n\nInvoice {entry.invoice_number} for {amt} is now {late} days past its "
                    f"due date ({entry.due_on:%b %d, %Y}).{partial} Could you let me know when I can expect "
                    f"payment? If something is holding it up, just reply and we can sort it out.\n\n"
                    f"Best,\n{freelancer}")
        else:
            tone, subject = "final", f"Final notice: invoice {entry.invoice_number} ({late} days overdue)"
            body = (f"Hi {first},\n\nInvoice {entry.invoice_number} for {amt} is {late} days overdue.{partial} "
                    f"Please arrange payment within 7 days or contact me to agree a payment plan.\n\n"
                    f"Regards,\n{freelancer}")
        return {"subject": subject, "note": body, "tone": tone, "days_overdue": late}


# ------------------------------------------------------------ planner protocol

class Planner(Protocol):
    def next_step(self, goal: str, history: list[dict], tools: dict[str, str]) -> dict:
        """Return {"tool": name, "args": {...}} or {"final": "text"}."""


class RulePlanner:
    """Deterministic stand-in for an LLM planner so the loop is testable offline.

    goal "invoice:<text>" -> create_invoice, then get_status for each draft
    goal "chase"          -> list_overdue, then send_reminder for each
    goal "status:<id>"    -> get_status
    """

    def next_step(self, goal: str, history: list[dict], tools: dict[str, str]) -> dict:
        done = [h for h in history if h["role"] == "tool"]
        if goal.startswith("invoice:"):
            if not done:
                return {"tool": "create_invoice", "args": {"text": goal[len("invoice:"):]}}
            created = done[0]["result"].get("invoices", [])
            if len(done) - 1 < len(created):
                return {"tool": "get_status", "args": {"invoice_id": created[len(done) - 1]["invoice_id"]}}
            return {"final": _summarise(done)}
        if goal == "chase":
            if not done:
                return {"tool": "list_overdue", "args": {}}
            overdue = done[0]["result"].get("overdue", [])
            if len(done) - 1 < len(overdue):
                return {"tool": "send_reminder", "args": {"invoice_id": overdue[len(done) - 1]["invoice_id"]}}
            return {"final": _summarise(done)}
        if goal.startswith("status:"):
            if not done:
                return {"tool": "get_status", "args": {"invoice_id": goal[len("status:"):]}}
            return {"final": _summarise(done)}
        return {"final": "I don't know how to do that."}


def _summarise(done: list[dict]) -> str:
    return "; ".join(f"{h['tool']} -> {h['result'].get('message', 'ok')}" for h in done)


# ------------------------------------------------------------ agent

class Agent:
    TOOLS = {
        "create_invoice": "Extract a job email into PayPal draft invoice(s). Queues send for human approval. args: text",
        "get_status": "Fetch invoice status from PayPal and sync the ledger. args: invoice_id",
        "send_reminder": "Draft a payment reminder for an overdue invoice and queue it for approval. args: invoice_id",
        "list_overdue": "List open invoices past their due date. args: none",
    }

    def __init__(self, client: InvoicingClient, invoicer: dict, extractor: Optional[Extractor] = None,
                 today: Callable[[], date] = date.today, drafter: Optional[ReminderDrafter] = None,
                 min_confidence: float = 0.5, reminder_cooldown_days: int = 7,
                 webhook_verifier: Optional[Callable[[dict, bytes], dict]] = None):
        self.client = GatedClient(client)
        self.invoicer = invoicer
        self.extractor = extractor or RulesExtractor()
        self.today = today
        self.drafter = drafter or TemplateReminderDrafter()
        self.min_confidence = min_confidence
        self.reminder_cooldown_days = reminder_cooldown_days
        self.webhook_verifier = webhook_verifier
        self.ledger: dict[str, LedgerEntry] = {}
        self.pending: dict[str, PendingAction] = {}
        self.audit: list[dict] = []
        self._seen_events: dict[str, str] = {}

    # -- tool loop
    def run(self, goal: str, planner: Planner, max_steps: int = 12) -> dict:
        history: list[dict] = [{"role": "user", "content": goal}]
        for _ in range(max_steps):
            step = planner.next_step(goal, history, self.TOOLS)
            if "final" in step:
                history.append({"role": "assistant", "content": step["final"]})
                return {"final": step["final"], "history": history, "pending": self.list_pending()}
            name, args = step.get("tool"), step.get("args") or {}
            if name not in self.TOOLS:
                result = {"ok": False, "message": f"unknown or forbidden tool {name!r}"}
            else:
                try:
                    result = getattr(self, f"tool_{name}")(**args)
                except ApprovalRequired as e:  # should never happen via tools; recorded if it does
                    result = {"ok": False, "message": str(e)}
                except (PayPalError, ValueError, TypeError) as e:
                    result = {"ok": False, "message": f"{type(e).__name__}: {e}"}
            self._log("tool", tool=name, args=args, ok=result.get("ok"))
            history.append({"role": "tool", "tool": name, "args": args, "result": result})
        return {"final": "step limit reached", "history": history, "pending": self.list_pending()}

    # -- tools (safe: never send, never move money)
    def tool_create_invoice(self, text: str) -> dict:
        ex = self.extractor.extract(text)
        # Extractor adapters may return a reviewed value with stale/no issues.
        # Admit the whole job before allocating even the first invoice number.
        issues = [*ex.issues]
        issues.extend(issue for issue in validate(ex) if issue not in issues)
        errors = [issue for issue in issues if issue.severity == "error"]
        if errors or ex.confidence < self.min_confidence:
            return {"ok": False, "needs_review": True, "confidence": ex.confidence,
                    "issues": [i.to_dict() for i in issues],
                    "message": f"needs human review (confidence {ex.confidence}, {len(errors)} error(s))"}
        created = []
        for part in split_by_currency(ex):
            number = self.client.generate_next_invoice_number().body["invoice_number"]
            note = "Thank you for your business."
            if ex.amount_paid > 0 and len(ex.currencies()) == 1:
                note += f" Deposit of {part.currency} {ex.amount_paid} received with thanks."
            body = build_invoice(part, self.invoicer, number, self.today(), note,
                                 allow_partial=ex.amount_paid > 0)
            invoice_due_on = (date.fromisoformat(body["detail"]["payment_term"]["due_date"])
                              if part.due_days is not None and part.due_days > 0 else None)
            resp = self.client.create_draft_invoice(body)
            inv_id = resp.body["href"].rsplit("/", 1)[-1] if "href" in resp.body else resp.body["id"]
            entry = LedgerEntry(inv_id, number, part.client_name, part.client_email, part.currency,
                                part.total(), part.due_days,
                                prepaid=ex.amount_paid if len(ex.currencies()) == 1 else Decimal(0),
                                invoice_due_on=invoice_due_on)
            self.ledger[inv_id] = entry
            summary = f"Send invoice {number} for {part.currency} {part.total():,} to {part.client_email}"
            if entry.prepaid:
                summary += f" and record {part.currency} {entry.prepaid:,} deposit already received"
            action = self._queue("send_invoice", inv_id, summary, {"invoice": body, "prepaid": str(entry.prepaid)})
            created.append({"invoice_id": inv_id, "invoice_number": number, "currency": part.currency,
                            "total": str(part.total()), "approval_id": action.id})
        return {"ok": True, "invoices": created, "confidence": ex.confidence,
                "issues": [i.to_dict() for i in issues],
                "message": f"{len(created)} draft(s) created; awaiting approval to send"}

    def tool_get_status(self, invoice_id: str) -> dict:
        inv = self._refresh_invoice(invoice_id)
        return {"ok": True, "invoice_id": invoice_id, "status": inv["status"],
                "due_amount": inv["due_amount"]["value"], "currency": inv["detail"]["currency_code"],
                "message": f"{invoice_id} is {inv['status']}"}

    def tool_list_overdue(self) -> dict:
        today = self.today()
        rows = [e.to_dict() | {"days_overdue": e.days_overdue(today)}
                for e in self.ledger.values()
                if e.status in OPEN_STATUSES and e.balance > 0 and e.days_overdue(today) > 0]
        return {"ok": True, "overdue": rows, "message": f"{len(rows)} overdue"}

    def tool_send_reminder(self, invoice_id: str) -> dict:
        e = self.ledger.get(invoice_id)
        if e is None:
            return {"ok": False, "message": f"unknown invoice {invoice_id}"}
        # Webhooks can be delayed or absent. Draft from the latest observed balance.
        inv = self._refresh_invoice(invoice_id)
        today = self.today()
        if e.status not in OPEN_STATUSES or e.balance <= 0:
            return {"ok": False, "message": f"{invoice_id} is {e.status}; no reminder needed"}
        if e.days_overdue(today) <= 0:
            return {"ok": False, "message": f"{invoice_id} not overdue (due {e.due_on})"}
        if e.last_reminder_on and (today - e.last_reminder_on).days < self.reminder_cooldown_days:
            return {"ok": False, "message": f"reminder already sent on {e.last_reminder_on}; cooling down"}
        if any(a.kind == "send_reminder" and a.invoice_id == invoice_id and a.status == "PENDING"
               for a in self.pending.values()):
            return {"ok": False, "message": "a reminder is already awaiting approval"}
        draft = self.drafter.draft(e, today, self.invoicer.get("name", ""))
        action = self._queue("send_reminder", invoice_id,
                             f"Send {draft['tone']} reminder for {e.invoice_number} ({draft['days_overdue']}d overdue, "
                             f"{e.currency} {e.balance:,} due) to {e.client_email}",
                             {"subject": draft["subject"], "note": draft["note"],
                              "reviewed_facts": self._reminder_facts(e, today),
                              "reviewed_invoice": self._invoice_facts(inv)})
        return {"ok": True, "approval_id": action.id, "draft": draft,
                "message": f"reminder drafted ({draft['tone']}); awaiting approval"}

    # -- human surface (NOT exposed to the planner)
    def list_pending(self) -> list[dict]:
        today = self.today()
        for entry in self.ledger.values():
            self._invalidate_reminders(entry, today)
        return [a.to_dict() for a in self.pending.values() if a.status == "PENDING"]

    def approve(self, action_id: str, approver: str = "human") -> dict:
        """Execute an approval, consuming its ID if the outgoing phase fails.

        Read-only preflight may be retried. Other ordinary errors leave
        a FAILED action with an UNKNOWN outcome: check the invoice before making
        a new approval. The original exception still reaches the caller.
        """
        a = self._pending_or_raise(action_id)
        if a.kind == "send_invoice":
            self._check_send_review(a)
            a = self._pending_or_raise(action_id)
        elif a.kind == "send_reminder":
            # Read-only preflight sits outside the effect-failure handler. A failed
            # read has sent nothing and may be retried explicitly with the same ID.
            self._refresh_invoice(a.invoice_id)
            a = self._pending_or_raise(action_id)
        try:
            if a.kind == "send_invoice":
                with self.client.permit("send_invoice", a.invoice_id):
                    r = self.client.send_invoice(a.invoice_id, {"send_to_invoicer": True, "send_to_recipient": True})
                e = self.ledger[a.invoice_id]
                e.status, e.sent_on = "SENT", self.today()
                result = {"payer_view": r.body.get("href")}
                if e.prepaid > 0:
                    with self.client.permit("record_payment", a.invoice_id):
                        p = self.client.record_payment(a.invoice_id, {
                            "method": "BANK_TRANSFER", "payment_date": self.today().isoformat(),
                            "amount": {"currency_code": e.currency, "value": str(e.prepaid)},
                            "note": "Deposit received before invoicing"})
                    result["deposit_payment_id"] = p.body["payment_id"]
                    self.tool_get_status(a.invoice_id)
            elif a.kind == "send_reminder":
                with self.client.permit("remind_invoice", a.invoice_id):
                    self.client.remind_invoice(a.invoice_id, {"subject": a.payload["subject"], "note": a.payload["note"],
                                                               "send_to_invoicer": True})
                e = self.ledger[a.invoice_id]
                e.reminders_sent += 1
                e.last_reminder_on = self.today()
                result = {"reminded": True}
            else:
                raise ValueError(f"unknown action kind {a.kind}")
        except PayPalError as err:
            a.status, a.result = "FAILED", err.body
            self._log("approve_failed", action=a.id, approver=approver, error=str(err))
            raise
        except Exception as err:
            # A lost response does not establish whether an outgoing effect happened.
            # Consume this ID so an explicit retry cannot repeat that effect.
            a.status = "FAILED"
            a.result = {
                "outcome": "UNKNOWN",
                "reason": "The outgoing action may have completed. Check the invoice before creating another approval.",
                "error_type": type(err).__name__,
            }
            self._log("approve_failed", action=a.id, approver=approver,
                      outcome="UNKNOWN", error=str(err), reason=a.result["reason"])
            raise
        a.status, a.result = "APPROVED", result
        self._log("approved", action=a.id, kind=a.kind, invoice=a.invoice_id, approver=approver)
        return result

    def reject(self, action_id: str, reason: str = "") -> None:
        a = self._pending_or_raise(action_id)
        a.status, a.result = "REJECTED", {"reason": reason}
        self._log("rejected", action=a.id, reason=reason)

    # -- webhooks
    def handle_webhook(self, raw_body: bytes, headers: Optional[dict] = None) -> dict:
        if self.webhook_verifier is not None:
            v = self.webhook_verifier(headers or {}, raw_body)
            if v.get("verification_status") != "SUCCESS":
                self._log("webhook_rejected", reason="bad signature")
                raise WebhookError("signature verification failed")
        ev = parse_webhook_event(raw_body)
        if not isinstance(ev.event_id, str) or not ev.event_id or ev.event_id.strip() != ev.event_id:
            raise WebhookError("event ID must be a nonempty string without surrounding whitespace")
        if not isinstance(ev.invoice_id, str) or not ev.invoice_id or ev.invoice_id.strip() != ev.invoice_id:
            raise WebhookError("invoice ID must be a nonempty string without surrounding whitespace")
        try:
            canonical = json.dumps(json.loads(raw_body), sort_keys=True, separators=(",", ":"), allow_nan=False)
        except (TypeError, ValueError) as err:
            raise WebhookError("event content must be finite JSON") from err
        digest = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
        prior = self._seen_events.get(ev.event_id)
        if prior is not None:
            if prior != digest:
                self._log("webhook_rejected", reason="event identity conflict", event_id=ev.event_id)
                raise WebhookError("Webhook event identity conflict")
            return {"ok": True, "duplicate": True, "invoice_id": ev.invoice_id}
        e = self.ledger.get(ev.invoice_id)
        if e is None:
            self._log("webhook_unknown_invoice", invoice=ev.invoice_id)
            return {"ok": False, "message": "unknown invoice"}
        prev = e.status
        # A signed notification can arrive late. Reuse the current-invoice read
        # and reminder invalidation before consuming its identity for replay.
        self._refresh_invoice(ev.invoice_id)
        self._seen_events[ev.event_id] = digest
        self._log("webhook", event_type=ev.event_type, invoice=ev.invoice_id,
                  transition=f"{prev}->{e.status}", reported_status=ev.status, source="current_invoice")
        return {"ok": True, "invoice_id": ev.invoice_id, "from": prev, "to": e.status}

    # -- internals
    def _send_review_content(self, invoice: dict, *, provider: bool = False) -> str:
        """Compare reviewed writable content, allowing only known response facts.

        Unfamiliar invoice fields remain in the comparison: a new recipient, fee,
        term, or display setting is not silently accepted as provider metadata.
        This represents the simple untaxed invoices emitted by build_invoice.
        """
        try:
            if (not isinstance(invoice, dict)
                    or any(not isinstance(invoice.get(key), dict)
                           for key in ("detail", "invoicer", "configuration"))
                    or not isinstance(invoice.get("primary_recipients"), list)):
                raise ValueError("invoice send review fields are incomplete or malformed")
            content = copy.deepcopy(invoice)
            detail = content["detail"]
            currency = detail["currency_code"]
            detail.pop("metadata", None)

            def decimal_text(value: Any) -> str:
                if not isinstance(value, str):
                    raise ValueError("invoice decimal fields must be strings")
                return self._amount_fact(value)

            items = content["items"]
            if not isinstance(items, list) or not items:
                raise ValueError("invoice review requires line items")
            total = Decimal(0)
            for item in items:
                item.pop("id", None)  # PayPal's read-only line-item identity.
                item["quantity"] = decimal_text(item["quantity"])
                unit = item["unit_amount"]
                if unit["currency_code"] != currency:
                    raise ValueError("invoice item currencies disagree")
                unit["value"] = decimal_text(unit["value"])
                total += Decimal(item["quantity"]) * Decimal(unit["value"])
            total = quantize(total, currency)

            def matches_amount(value: dict, expected: Decimal) -> bool:
                return (isinstance(value, dict) and set(value) == {"currency_code", "value"}
                        and value["currency_code"] == currency
                        and Decimal(decimal_text(value["value"])) == expected)

            if provider:
                for key in ("id", "parent_id", "status", "links"):
                    content.pop(key, None)
                amount = content["amount"]
                summary = {key: amount[key] for key in ("currency_code", "value")}
                if not matches_amount(summary, total) or not matches_amount(content["due_amount"], total):
                    raise ValueError("provider draft totals do not match its reviewed line items")
                del content["due_amount"]
                # Keep every adjustment or unfamiliar summary field visible to
                # comparison. Only the generated total/subtotal may disappear.
                del amount["currency_code"], amount["value"]
                if "breakdown" in amount:
                    breakdown = amount["breakdown"]
                    if not isinstance(breakdown, dict):
                        raise ValueError("provider draft amount breakdown is malformed")
                    if "item_total" in breakdown:
                        if not matches_amount(breakdown["item_total"], total):
                            raise ValueError("provider draft subtotal is inconsistent")
                        del breakdown["item_total"]
                    if not breakdown:
                        del amount["breakdown"]
                if not amount:
                    del content["amount"]
                for key, aggregate in (("payments", "paid_amount"), ("refunds", "refund_amount")):
                    if key not in content:
                        continue
                    state = content[key]
                    if (set(state) - {aggregate, "transactions"}
                            or state.get("transactions", []) != []
                            or (aggregate in state and not matches_amount(state[aggregate], Decimal(0)))):
                        raise ValueError("provider draft already has payment or refund facts")
                    del content[key]
                if "gratuity" in content:
                    if not matches_amount(content["gratuity"], Decimal(0)):
                        raise ValueError("provider draft already has a gratuity")
                    del content["gratuity"]
            if content.get("additional_recipients") == []:
                del content["additional_recipients"]
            return json.dumps(content, sort_keys=True, separators=(",", ":"), allow_nan=False)
        except (KeyError, TypeError, AttributeError, ArithmeticError) as err:
            raise ValueError("invoice send review is incomplete or malformed; no send attempted") from err

    def _check_send_review(self, action: PendingAction) -> None:
        # Read before any permit; a transport/malformed read leaves the original
        # review pending and unchanged. This GET/POST boundary is not atomic.
        invoice = self.client.get_invoice(action.invoice_id).body
        if (not isinstance(invoice, dict) or invoice.get("id") != action.invoice_id
                or not isinstance(invoice.get("status"), str) or invoice["status"] not in STATUSES):
            raise ValueError("provider invoice identity/status is unavailable; no send attempted")
        reason = None
        if invoice["status"] != "DRAFT":
            reason = "auto: invoice is no longer a draft; check the invoice before a new review"
        else:
            reviewed = self._send_review_content(action.payload["invoice"])
            current = self._send_review_content(invoice, provider=True)
            entry = self.ledger[action.invoice_id]
            if (current != reviewed
                    or self._amount_fact(entry.prepaid) != self._amount_fact(action.payload["prepaid"])
                    or entry.currency != action.payload["invoice"]["detail"]["currency_code"]):
                reason = "auto: invoice changed since review; check the invoice and create a fresh review before sending"
        if reason:
            action.status, action.result = "REJECTED", {"reason": reason}
            self._log("invoice_send_invalidated", action=action.id, invoice=action.invoice_id, reason=reason)

    @staticmethod
    def _amount_fact(value: Any) -> str:
        amount = Decimal(str(value))
        if not amount.is_finite():
            raise ValueError("invoice amount must be finite before reminder review")
        text = format(amount, "f")
        if "." in text:
            text = text.rstrip("0").rstrip(".")
        return "0" if amount == 0 else text

    def _invoice_facts(self, inv: dict) -> str:
        """Stable presentation facts; delivery metadata is not reminder content."""
        detail = inv.get("detail", {})

        def money(value: Any) -> Any:
            if value is None:
                return None
            return {"currency_code": value.get("currency_code"),
                    "value": self._amount_fact(value["value"])}

        facts = {"id": inv.get("id"), "status": inv["status"],
                 "invoice_number": detail.get("invoice_number"),
                 "currency_code": detail.get("currency_code"),
                 "payment_term": detail.get("payment_term"),
                 "primary_recipients": inv.get("primary_recipients"),
                 "amount": money(inv.get("amount")),
                 "due_amount": money(inv.get("due_amount")),
                 "paid_amount": money(inv["payments"]["paid_amount"])}
        return json.dumps(facts, sort_keys=True, separators=(",", ":"), allow_nan=False)

    def _reminder_facts(self, e: LedgerEntry, today: date) -> dict:
        return {"reviewed_on": today.isoformat(), "invoice_id": e.invoice_id,
                "invoice_number": e.invoice_number, "client_name": e.client_name,
                "client_email": e.client_email, "currency": e.currency,
                "total": self._amount_fact(e.total),
                "paid_amount": self._amount_fact(e.paid_amount),
                "balance": self._amount_fact(e.balance), "status": e.status,
                "due_on": e.due_on.isoformat() if e.due_on else None,
                "last_reminder_on": e.last_reminder_on.isoformat() if e.last_reminder_on else None,
                "reminders_sent": e.reminders_sent,
                "freelancer": self.invoicer.get("name", "")}

    def _invalidate_reminders(self, e: LedgerEntry, today: date,
                              invoice_facts: Optional[str] = None) -> None:
        for action in self.pending.values():
            if (action.kind != "send_reminder" or action.invoice_id != e.invoice_id
                    or action.status != "PENDING"):
                continue
            reason = None
            if e.status not in OPEN_STATUSES or e.balance <= 0:
                reason = "auto: invoice no longer needs a reminder"
            elif action.payload.get("reviewed_facts") != self._reminder_facts(e, today):
                reason = "auto: reminder facts or review date changed; draft a new reminder for review"
            elif (invoice_facts is not None
                  and action.payload.get("reviewed_invoice") != invoice_facts):
                reason = "auto: provider invoice changed; draft a new reminder for review"
            if reason:
                # Retain the reviewed subject/note and action ID as rejected history.
                action.status, action.result = "REJECTED", {"reason": reason}
                self._log("reminder_invalidated", action=action.id, invoice=e.invoice_id, reason=reason)

    def _refresh_invoice(self, invoice_id: str) -> dict:
        inv = self.client.get_invoice(invoice_id).body
        # Parse all facts before mutating cached state; an unavailable/malformed
        # read must not open the approval permit or manufacture a successful send.
        presentation = self._invoice_presentation(invoice_id, inv)
        facts = self._invoice_facts(inv)
        e = self.ledger.get(invoice_id)
        if e:
            for name, value in presentation.items():
                setattr(e, name, value)
            self._invalidate_reminders(e, self.today(), facts)
        return inv

    def _invoice_presentation(self, invoice_id: str, inv: dict) -> dict:
        """Validate a complete fresh presentation before replacing cached facts.

        An unsupported/ambiguous invoice is held, never rebound to old local words.
        The current product supports exactly one billing recipient and an explicit
        provider due date, NO_DUE_DATE, or an unresolved receipt term on a draft.
        """
        try:
            if inv["id"] != invoice_id:
                raise ValueError("provider returned a different invoice")
            detail = inv["detail"]
            currency = detail["currency_code"]
            number = detail["invoice_number"]
            status = inv["status"]
            if not all(isinstance(v, str) and v.strip() for v in (currency, number, status)):
                raise ValueError("provider invoice identity/status is incomplete")

            def amount(field: dict) -> Decimal:
                if field["currency_code"] != currency:
                    raise ValueError("provider invoice currencies disagree")
                value = Decimal(self._amount_fact(field["value"]))
                if value < 0:
                    raise ValueError("provider invoice amounts must not be negative")
                return value

            total = amount(inv["amount"])
            paid = amount(inv["payments"]["paid_amount"])
            due = amount(inv["due_amount"])
            if due != max(total - paid, Decimal(0)):
                raise ValueError("provider balance cannot be represented by this invoice ledger")

            term = detail["payment_term"]
            receipt_pending = (status == "DRAFT" and term.get("term_type") == "DUE_ON_RECEIPT"
                               and "due_date" not in term)
            if term.get("term_type") == "NO_DUE_DATE":
                if term.get("due_date"):
                    raise ValueError("provider due-date fields disagree")
                due_on = None
            elif receipt_pending:
                due_on = None
            else:
                due_on = date.fromisoformat(term["due_date"])

            recipients = inv["primary_recipients"]
            if not isinstance(recipients, list) or len(recipients) != 1:
                raise ValueError("reminder review requires exactly one billing recipient")
            billing = recipients[0]["billing_info"]
            email = billing["email_address"]
            if not isinstance(email, str) or not email.strip():
                raise ValueError("provider billing email is missing")
            name = billing.get("name") or {}
            parts = [name.get("given_name"), name.get("surname")]
            if any(part is not None and not isinstance(part, str) for part in parts):
                raise ValueError("provider billing name is malformed")
            client_name = " ".join(part.strip() for part in parts if part and part.strip()) or None
            return {"status": status, "total": total, "paid_amount": paid,
                    "currency": currency, "invoice_number": number,
                    "client_email": email, "client_name": client_name,
                    "provider_due_on": due_on, "provider_due_known": not receipt_pending,
                    "provider_receipt_pending": receipt_pending}
        except (KeyError, TypeError, AttributeError, ArithmeticError) as err:
            raise ValueError("provider invoice facts are incomplete or malformed; review is unavailable") from err

    def _queue(self, kind: str, invoice_id: str, summary: str, payload: dict) -> PendingAction:
        a = PendingAction("apv_" + uuid.uuid4().hex[:10], kind, invoice_id, summary, payload)
        self.pending[a.id] = a
        self._log("queued", action=a.id, kind=kind, invoice=invoice_id)
        return a

    def _pending_or_raise(self, action_id: str) -> PendingAction:
        a = self.pending.get(action_id)
        if a is None:
            raise KeyError(f"no such action {action_id}")
        if a.status != "PENDING":
            reason = a.result.get("reason") if isinstance(a.result, dict) else None
            suffix = f": {reason}" if reason else ""
            raise ValueError(f"action {action_id} already {a.status}{suffix}")
        return a

    def _log(self, event: str, **kw: Any) -> None:
        self.audit.append({"at": datetime.now(timezone.utc).isoformat(), "event": event,
                           **{k: (str(v) if isinstance(v, Decimal) else v) for k, v in kw.items()}})

    def export_state(self) -> str:
        return json.dumps({"ledger": [e.to_dict() for e in self.ledger.values()],
                           "pending": self.list_pending(), "audit": self.audit}, indent=2, default=str)

"""Job email / plain text -> structured invoice draft.

Two extractors share one output type (`Extraction`) and one validator:

* `RulesExtractor`  - deterministic regex/heuristic parser. No network, no model.
* `LLMExtractor`    - pluggable: you inject `complete(prompt) -> str`. No live LLM
                      call is made anywhere in this repo; tests use a fake.
* `HybridExtractor` - rules first, falls back to the LLM when confidence is low.

Every result has a 0..1 `confidence` and field-level `issues`
(severity: error | warning | info). Errors block invoice creation in the agent
until a human fixes them.
"""
from __future__ import annotations

import json
import re
from collections import Counter
from dataclasses import dataclass, field
from decimal import ROUND_HALF_UP, Decimal, DecimalException, InvalidOperation, localcontext
from typing import Any, Callable, Optional, Protocol

# Subset of PayPal-supported currency codes.
# https://developer.paypal.com/api/rest/reference/currency-codes/
PAYPAL_CURRENCIES = {
    "AUD", "BRL", "CAD", "CNY", "CZK", "DKK", "EUR", "HKD", "HUF", "ILS", "JPY",
    "MYR", "MXN", "TWD", "NZD", "NOK", "PHP", "PLN", "GBP", "SGD", "SEK", "CHF",
    "THB", "USD",
}
# Currencies PayPal treats as having no decimal places (same reference page).
ZERO_DECIMAL_CURRENCIES = {"JPY", "HUF", "TWD"}
DOLLAR_CURRENCIES = {"USD", "CAD", "AUD", "NZD", "SGD", "HKD", "MXN", "TWD"}

SYMBOLS = {
    "US$": "USD", "CA$": "CAD", "C$": "CAD", "AU$": "AUD", "A$": "AUD",
    "NZ$": "NZD", "$": "USD", "€": "EUR", "£": "GBP", "¥": "JPY",
}

SEVERITY_PENALTY = {"error": 0.25, "warning": 0.10, "info": 0.0}

EMAIL_RE = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")
_SYM = "|".join(re.escape(s) for s in sorted(SYMBOLS, key=len, reverse=True))
_CODE = "|".join(sorted(PAYPAL_CURRENCIES))
# Consume a complete number-like token first. _dec checks comma grouping, so
# malformed text cannot be silently shortened to its first valid numeric prefix.
_NUM = r"[+-]?(?:\d(?:[\d,]*\d)?(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?"
_NO_SUFFIX = r"(?!\d|[\d.,]*[kKmM]\b|[eE]|[.,]\d)"
MONEY_RE = re.compile(
    rf"(?:(?P<sign>[+-])?(?P<pre>{_SYM}|\b(?:{_CODE})\b)\s?(?P<num>{_NUM}){_NO_SUFFIX}"
    rf"|(?<![\w.,])(?P<num2>{_NUM}){_NO_SUFFIX}\s?(?P<post>\b(?:{_CODE})\b|€|£))"
)
_MONEY_CANDIDATE_RE = re.compile(rf"(?:{_SYM}|\b(?:{_CODE})\b)\s*(?:[+\-\d(]|\.\d)")
_GROUPED_NUMBER_RE = re.compile(r"[+-]?\d{1,3}(?:,\d{3})+(?:\.\d+)?(?:[eE][+-]?\d+)?")

_WORD_NUMS = {
    "one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7,
    "eight": 8, "nine": 9, "ten": 10, "eleven": 11, "twelve": 12,
}
_Q_NUMBER = r"[+-]?(?:\d{1,3}(?:,\d{3})+(?:\.\d+)?|\d+(?:\.\d+)?|\.\d+)"
_Q = (
    r"(?:(?:~\s*|approx\.?\s*|about\s+|around\s+|roughly\s+)?"
    + _Q_NUMBER + r"(?:\s*(?:-|–|to)\s*" + _Q_NUMBER + r")?"
    r"|(?:a\s+few|a\s+couple(?:\s+of)?|several|some|"
    + "|".join(_WORD_NUMS) + r")\b)"
)
_UNITS = (
    r"(?:hours?|hrs?|h|days?|pages?|words?|units?|revisions?|sessions?|items?|"
    r"pcs?|photos?|articles?|posts?|videos?|weeks?|months?|screens?|episodes?)"
)
_ITEM_PATTERNS = [
    # "3 x Logo concepts @ $250 each"
    re.compile(rf"^(?P<qty>{_Q})\s*(?:x|×|\*)\s*(?P<desc>.+?)\s*(?:@|\bat\b|\bfor\b)\s*<M>", re.I),
    # "12 hours of copy editing at £45/hr"
    re.compile(rf"^(?P<qty>{_Q})\s*(?P<unit>{_UNITS})\b\s+(?:of\s+)?(?P<desc>.+?)\s*(?:@|\bat\b|\bfor\b|x|×)\s*<M>", re.I),
    # "Proofreading: 3 hrs @ £40/hr"
    re.compile(rf"^(?P<desc>.+?)\s*[:–—-]\s*(?P<qty>{_Q})\s*(?P<unit>[A-Za-z]+\.?)?\s*(?:@|\bat\b|x|×)\s*<M>", re.I),
    # "4 product photos at $75 each" / "a few revisions at $40 each"
    re.compile(rf"^(?P<qty>{_Q})\s+(?P<desc>.+?)\s*(?:@|\bat\b)\s*<M>", re.I),
    # "Website build — €2,400.00"  (qty 1; separator must touch the price)
    re.compile(r"^(?P<desc>.+?)\s*(?:[:–—-]|@|\bat\b|\bfor\b)\s*<M>", re.I),
]
_BULLET_RE = re.compile(r"^\s*(?:[-*•·]|\d+[.)])\s+")
_PAID_RE = re.compile(
    r"\b(deposit|already paid|paid upfront|advance payment|prepaid|have paid|we paid|retainer paid)\b", re.I
)
_PAYMENT_KIND = r"(?:deposit|retainer|advance payment|payment)"
_PAYMENT_AMOUNT = (
    rf"(?:(?:(?:a|an|the) )?<M>(?: {_PAYMENT_KIND})?"
    rf"|(?:(?:a|an|the) )?{_PAYMENT_KIND} of <M>)"
)
_PAID_CONFIRMED_RE = re.compile(
    rf"(?:(?:(?:we|i) (?:have |had )?(?:already )?paid|already paid|paid upfront|prepaid)"
    rf":? {_PAYMENT_AMOUNT}"
    rf"|{_PAYMENT_AMOUNT} (?:(?:has|have|had) (?:already )?been (?:paid|received)"
    rf"|(?:was|were) (?:already )?(?:paid|received)|(?:already )?paid)"
    rf"|{_PAYMENT_KIND} (?:already )?paid: <M>)"
    r"(?: (?:upfront|in advance|yesterday|today|last week|last month)"
    r"| (?:by|via) (?:bank transfer|wire transfer|cash|check|cheque))*[.!]?", re.I
)
_TOTAL_RE = re.compile(r"\b(total|subtotal|budget|balance|altogether)\b", re.I)
_BILLING_RE = re.compile(
    r"\b(?:send|email|address|forward)\s+(?:the\s+|your\s+|all\s+)?invoices?\s+to\s+(" + EMAIL_RE.pattern + ")",
    re.I,
)
_DOC_CCY_RE = re.compile(
    rf"\b(?:prices?|amounts?|rates?|figures?|billed|bill|invoice)\s+(?:are\s+|is\s+|us\s+)?in\s+({_CODE})\b",
    re.I,
)
_DUE_PATTERNS = [
    re.compile(r"\bnet\s*[- ]?\s*(\d{1,3})\b", re.I),
    re.compile(r"\bdue\s+(?:with)?in\s+(\d{1,3})\s+days\b", re.I),
    re.compile(r"\b(?:pay|paid|payment)\b[^.\n]{0,30}?\bwithin\s+(\d{1,3})\s+days\b", re.I),
    re.compile(r"\bwithin\s+(\d{1,3})\s+days\b", re.I),
    re.compile(r"\b(\d{1,3})[- ]day\s+(?:payment\s+)?terms?\b", re.I),
]
_DUE_ON_RECEIPT_RE = re.compile(r"\b(?:due\s+(?:up)?on\s+receipt|payable\s+immediately)\b", re.I)
_SIGNOFF_RE = re.compile(
    r"^(thanks|thank you|thx|best|regards|cheers|best regards|kind regards|warm regards|sincerely)[,!.]?\s*$", re.I
)
_HEADER_KEYS = {"from", "to", "cc", "subject", "date", "reply-to"}


@dataclass
class Issue:
    field: str
    severity: str  # error | warning | info
    message: str

    def to_dict(self) -> dict:
        return {"field": self.field, "severity": self.severity, "message": self.message}


@dataclass
class LineItem:
    desc: str
    qty: Optional[Decimal]
    unit_price: Decimal
    currency: Optional[str] = None
    unit: Optional[str] = None

    def amount(self) -> Decimal:
        return (self.qty or Decimal(0)) * self.unit_price

    def to_dict(self) -> dict:
        return {
            "desc": self.desc,
            "qty": None if self.qty is None else str(self.qty),
            "unit_price": str(self.unit_price),
            "currency": self.currency,
            "unit": self.unit,
        }


@dataclass
class Extraction:
    client_name: Optional[str]
    client_email: Optional[str]
    currency: Optional[str]
    line_items: list[LineItem]
    due_days: Optional[int]
    amount_paid: Decimal = Decimal(0)
    issues: list[Issue] = field(default_factory=list)
    confidence: float = 0.0
    source: str = "rules"

    @property
    def errors(self) -> list[Issue]:
        return [i for i in self.issues if i.severity == "error"]

    def currencies(self) -> list[str]:
        return sorted({li.currency for li in self.line_items if li.currency})

    def total(self) -> Decimal:
        return sum((li.amount() for li in self.line_items), Decimal(0))

    def to_dict(self) -> dict:
        return {
            "client_name": self.client_name,
            "client_email": self.client_email,
            "currency": self.currency,
            "line_items": [li.to_dict() for li in self.line_items],
            "due_days": self.due_days,
            "amount_paid": str(self.amount_paid),
            "total": str(self.total()),
            "confidence": self.confidence,
            "issues": [i.to_dict() for i in self.issues],
            "source": self.source,
        }

    @classmethod
    def from_dict(cls, d: dict) -> "Extraction":
        items = []
        for li in d.get("line_items") or []:
            qty = li.get("qty")
            items.append(
                LineItem(
                    desc=str(li.get("desc") or "").strip(),
                    qty=None if qty in (None, "") else _dec(qty),
                    unit_price=_dec(li.get("unit_price", 0)),
                    currency=(li.get("currency") or d.get("currency") or None),
                    unit=li.get("unit"),
                )
            )
        ex = cls(
            client_name=d.get("client_name"),
            client_email=d.get("client_email"),
            currency=d.get("currency"),
            line_items=items,
            due_days=None if d.get("due_days") is None else int(d["due_days"]),
            amount_paid=_dec(d.get("amount_paid") or 0),
            issues=[Issue(**i) for i in d.get("issues") or []],
            confidence=float(d.get("confidence") or 0.0),
            source=d.get("source", "dict"),
        )
        return ex


class Extractor(Protocol):
    def extract(self, text: str) -> Extraction: ...


# ----------------------------------------------------------------- helpers

def _dec(v: Any) -> Decimal:
    literal = str(v).strip()
    if "," in literal and not _GROUPED_NUMBER_RE.fullmatch(literal):
        raise ValueError(f"ambiguous number grouping: {v!r}")
    try:
        value = Decimal(literal.replace(",", ""))
    except (InvalidOperation, AttributeError):
        raise ValueError(f"not a number: {v!r}")
    if not value.is_finite():
        raise ValueError(f"not a finite number: {v!r}")
    # No accepted invoice can represent more than 28 integer digits in the
    # existing Decimal context. Refuse before rules summaries or deposit sums
    # perform arithmetic, including newly recognized exponent notation.
    if value.adjusted() > 27:
        raise ValueError(f"number exceeds supported invoice arithmetic range: {v!r}")
    return value


def quantize(value: Decimal, currency: Optional[str]) -> Decimal:
    exp = Decimal("1") if currency in ZERO_DECIMAL_CURRENCIES else Decimal("0.01")
    return value.quantize(exp, rounding=ROUND_HALF_UP)


def compute_confidence(issues: list[Issue]) -> float:
    score = 1.0 - sum(SEVERITY_PENALTY.get(i.severity, 0.0) for i in issues)
    return round(max(0.0, min(1.0, score)), 2)


def parse_money(m: re.Match) -> tuple[Optional[str], Decimal, str]:
    """Return (currency_code, amount, raw_currency_token)."""
    tok = m.group("pre") or m.group("post") or ""
    num = m.group("num") or m.group("num2")
    code = SYMBOLS.get(tok, tok.upper() if tok.upper() in PAYPAL_CURRENCIES else None)
    sign = m.group("sign")
    if sign and num.startswith(("+", "-")):
        raise ValueError("conflicting amount signs")
    return code, _dec((sign or "") + num), tok


def parse_qty(raw: str) -> tuple[Optional[Decimal], Optional[str]]:
    """Return (qty, ambiguity_reason). qty None means unknowable."""
    s = raw.strip().lower()
    if re.fullmatch(r"a\s+few|several|some", s):
        return None, f"vague quantity '{raw.strip()}'"
    if re.fullmatch(r"a\s+couple(?:\s+of)?", s):
        return Decimal(2), f"'{raw.strip()}' interpreted as 2"
    if s in _WORD_NUMS:
        return Decimal(_WORD_NUMS[s]), None
    approx = re.match(r"^(?:~\s*|approx\.?\s*|about\s+|around\s+|roughly\s+)", s)
    numeric = s[approx.end():] if approx else s
    rng = re.fullmatch(rf"({_Q_NUMBER})\s*(?:-|–|to)\s*({_Q_NUMBER})", numeric)
    if rng:
        try:
            lo = _dec(rng.group(1))
        except ValueError as error:
            return None, f"unreadable quantity '{raw.strip()}' ({error})"
        return lo, f"range '{raw.strip()}' - used lower bound {lo}; confirm with client"
    n = re.fullmatch(_Q_NUMBER, numeric)
    if not n:
        return None, f"unreadable quantity '{raw.strip()}'"
    try:
        q = _dec(n.group(0))
    except ValueError as error:
        return None, f"unreadable quantity '{raw.strip()}' ({error})"
    if approx:
        return q, f"approximate quantity '{raw.strip()}' - used {q}"
    return q, None


def _split_headers(text: str) -> tuple[dict[str, str], str]:
    lines = text.replace("\r\n", "\n").split("\n")
    headers: dict[str, str] = {}
    i = 0
    while i < len(lines):
        m = re.match(r"^([A-Za-z-]+):\s*(.*)$", lines[i])
        if not m or m.group(1).lower() not in _HEADER_KEYS:
            break
        headers[m.group(1).lower()] = m.group(2).strip()
        i += 1
    return headers, "\n".join(lines[i:])


def _parse_address(value: str) -> tuple[Optional[str], Optional[str]]:
    if not value:
        return None, None
    em = EMAIL_RE.search(value)
    email = em.group(0).lower() if em else None
    name = value
    if em:
        name = value[: em.start()] + value[em.end():]
    name = re.sub(r"[<>\"]", " ", name)
    paren = re.search(r"\(([^)]+)\)", name)  # "佐藤 健 (Ken Sato)" -> prefer latin alias
    if paren:
        name = paren.group(1)
    name = re.sub(r"\s+", " ", name).strip(" ,")
    return (name or None), email


def _signature_name(body: str) -> Optional[str]:
    lines = [l.strip() for l in body.split("\n")]
    for i, line in enumerate(lines):
        if _SIGNOFF_RE.match(line):
            for nxt in lines[i + 1:]:
                if not nxt:
                    continue
                if len(nxt.split()) <= 4 and not re.search(r"[\d@]", nxt):
                    return nxt
                break
    return None


# --------------------------------------------------------------- validation

def validate(ex: Extraction, source_text: Optional[str] = None) -> list[Issue]:
    """Checks shared by every extractor. Returns NEW issues (does not mutate)."""
    out: list[Issue] = []

    def finite(value: Any) -> bool:
        return (isinstance(value, (Decimal, int)) and not isinstance(value, bool)
                and (not isinstance(value, Decimal) or value.is_finite()))

    def money(value: Any, currency: Optional[str], field: str, *, positive: bool) -> bool:
        if not finite(value):
            out.append(Issue(field, "error", "Amount must be a finite number."))
            return False
        if value < 0 or (positive and value == 0):
            out.append(Issue(field, "error", "Amount must be positive." if positive else "Prior payment cannot be negative."))
            return False
        if currency not in PAYPAL_CURRENCIES:
            return False  # the currency issue is recorded separately
        try:
            rounded = quantize(Decimal(value), currency)
        except DecimalException:
            out.append(Issue(field, "error", "Amount is too large to represent at invoice precision."))
            return False
        if rounded != value:
            message = (f"{currency} does not support decimals on PayPal." if currency in ZERO_DECIMAL_CURRENCIES
                       else f"Amount has fractions smaller than a {currency} currency unit; review it before drafting.")
            out.append(Issue(field, "error", message))
            return False
        return True

    if not ex.client_email:
        out.append(Issue("client_email", "error", "No client email found; PayPal needs a recipient email to send an invoice."))
    elif not EMAIL_RE.fullmatch(ex.client_email):
        out.append(Issue("client_email", "error", f"Malformed email {ex.client_email!r}."))
    elif source_text is not None and ex.client_email.lower() not in source_text.lower():
        out.append(Issue("client_email", "error", f"{ex.client_email} does not appear in the source text (possible hallucination)."))
    if not ex.client_name:
        out.append(Issue("client_name", "warning", "No client name found."))
    if not ex.line_items:
        out.append(Issue("line_items", "error", "No priced line items found."))
    valid_amounts = True
    currency_amounts: dict[str, list[Decimal]] = {}
    for n, li in enumerate(ex.line_items):
        qty_ok = finite(li.qty)
        if not qty_ok:
            out.append(Issue(f"line_items[{n}].qty", "error", "Quantity is required and must be a finite number."))
        elif not 0 < li.qty <= 1000000:
            out.append(Issue(f"line_items[{n}].qty", "error", "Quantity must be positive and no greater than 1000000."))
            qty_ok = False
        elif Decimal(li.qty).quantize(Decimal("0.00001")) != li.qty:
            out.append(Issue(f"line_items[{n}].qty", "error", "Quantity supports at most five decimal places."))
            qty_ok = False
        if not li.currency:
            out.append(Issue(f"line_items[{n}].currency", "error", "Currency unknown for this item."))
        elif li.currency not in PAYPAL_CURRENCIES:
            out.append(Issue(f"line_items[{n}].currency", "error", f"{li.currency} is not a supported invoice currency."))
        price_ok = money(li.unit_price, li.currency, f"line_items[{n}].unit_price", positive=True)
        if qty_ok and price_ok:
            # Refuse implicit sub-unit rounding, including fractional quantities.
            # This is Ledgerly's exact-value policy, not a claimed PayPal rejection.
            with localcontext() as ctx:
                ctx.prec = max(ctx.prec, len(Decimal(li.qty).as_tuple().digits)
                               + len(Decimal(li.unit_price).as_tuple().digits) + 1)
                amount = Decimal(li.qty) * Decimal(li.unit_price)
            amount_ok = money(amount, li.currency, f"line_items[{n}].amount", positive=True)
            valid_amounts = valid_amounts and amount_ok
            if amount_ok:
                currency_amounts.setdefault(li.currency, []).append(amount)
        else:
            valid_amounts = False
    currency_totals: dict[str, Decimal] = {}
    for currency, amounts in currency_amounts.items():
        with localcontext() as ctx:
            ctx.prec = max(ctx.prec, max(len(amount.as_tuple().digits) for amount in amounts)
                           + len(str(len(amounts))) + 1)
            total = sum(amounts, Decimal(0))
        currency_totals[currency] = total
        if not money(total, currency, f"currency_totals[{currency}]", positive=True):
            valid_amounts = False
    ccys = ex.currencies()
    if len(ccys) > 1:
        out.append(Issue("currency", "warning",
                         f"Multiple currencies {ccys}; a PayPal invoice has one currency_code, so this will be split into {len(ccys)} invoices."))
    if not ex.currency:
        out.append(Issue("currency", "error", "Invoice currency is required."))
    elif ex.currency not in PAYPAL_CURRENCIES:
        out.append(Issue("currency", "error", f"{ex.currency} is not a PayPal-supported currency."))
    elif ccys and ex.currency not in ccys:
        out.append(Issue("currency", "error", f"Invoice currency {ex.currency} does not match item currencies {ccys}; review rather than convert the amounts."))
    if ex.due_days is not None and not (0 <= ex.due_days <= 365):
        out.append(Issue("due_days", "error", f"Implausible payment term: {ex.due_days} days."))
    paid_ok = money(ex.amount_paid, ex.currency, "amount_paid", positive=False)
    if paid_ok and ex.amount_paid > 0:
        if len(ccys) > 1:
            out.append(Issue("amount_paid", "error", "Prior payment reported on a multi-currency job; assign it manually."))
        elif valid_amounts and ex.currency in currency_totals and ex.amount_paid >= currency_totals[ex.currency]:
            out.append(Issue("amount_paid", "error", f"Reported payment {ex.amount_paid} >= invoice total {currency_totals[ex.currency]}."))
    return out


# ------------------------------------------------------------ rules extractor

class RulesExtractor:
    name = "rules"

    def __init__(self, default_due_days: int = 30):
        self.default_due_days = default_due_days

    def extract(self, text: str) -> Extraction:
        headers, body = _split_headers(text)
        live = "\n".join(l for l in body.split("\n") if not l.lstrip().startswith(">"))  # ignore quoted thread
        issues: list[Issue] = []

        name, email = _parse_address(headers.get("from", ""))
        _, to_email = _parse_address(headers.get("to", ""))
        billing = _BILLING_RE.search(live)
        if billing:
            b = billing.group(1).rstrip(".").lower()
            if email and b != email:
                issues.append(Issue("client_email", "info", f"Billing address {b} differs from sender {email}; using billing address."))
            email = b
        if not email:
            found = [e.lower() for e in EMAIL_RE.findall(live) if e.lower() != (to_email or "")]
            if found:
                email = found[0]
                issues.append(Issue("client_email", "info", f"Client email {email} taken from message body."))
        if not name:
            name = _signature_name(live)
            if name:
                issues.append(Issue("client_name", "info", "Client name taken from signature."))

        doc_ccy_m = _DOC_CCY_RE.search(live)
        doc_ccy = doc_ccy_m.group(1).upper() if doc_ccy_m else None

        items, paid, stated_totals, item_issues = self._line_items(live, doc_ccy)
        issues += item_issues

        ccy_counts = Counter(li.currency for li in items if li.currency)
        currency = ccy_counts.most_common(1)[0][0] if ccy_counts else doc_ccy

        due_days = self._due_days(live)
        if due_days is None:
            due_days = self.default_due_days
            issues.append(Issue("due_days", "warning", f"No payment terms found; defaulted to Net {self.default_due_days}."))

        ex = Extraction(name, email, currency, items, due_days, paid, source=self.name)
        if paid > 0:
            issues.append(Issue("amount_paid", "info", f"Client reports {paid} already paid; will be recorded against the invoice after approval."))
        for ccy, amt in stated_totals:
            if items and (ccy in (None, currency)) and len(ex.currencies()) <= 1:
                if amt not in (ex.total(), ex.total() - paid):
                    issues.append(Issue("line_items", "warning", f"Stated total/budget {amt} differs from computed total {ex.total()}."))
            elif not items:
                issues.append(Issue("line_items", "info", f"Message mentions a total/budget of {ccy or ''} {amt} but no itemised work."))
        ex.issues = issues + validate(ex, text)
        ex.confidence = compute_confidence(ex.issues)
        return ex

    def _due_days(self, text: str) -> Optional[int]:
        if _DUE_ON_RECEIPT_RE.search(text):
            return 0
        for pat in _DUE_PATTERNS:
            m = pat.search(text)
            if m:
                return int(m.group(1))
        return None

    def _line_items(self, body: str, doc_ccy: Optional[str]):
        lines = body.split("\n")
        items: list[LineItem] = []
        issues: list[Issue] = []
        stated: list[tuple[Optional[str], Decimal]] = []
        paid = Decimal(0)
        payments: list[tuple[Optional[str], Decimal]] = []

        t_items, consumed, t_issues, t_totals = self._table(lines, doc_ccy)
        items += t_items
        issues += t_issues
        stated += t_totals

        for idx, raw in enumerate(lines):
            if idx in consumed:
                continue
            line = _BULLET_RE.sub("", raw).strip()
            if not line:
                continue
            monies = list(MONEY_RE.finditer(line))
            if not monies:
                if _MONEY_CANDIDATE_RE.search(line):
                    issues.append(Issue("line_items", "error", f"Ambiguous monetary amount; review the entire priced line: {line!r}"))
                continue
            try:
                ccy, amt, tok = parse_money(monies[0])
            except ValueError as error:
                issues.append(Issue("line_items", "error", f"Unreadable monetary amount ({error}); review line: {line!r}"))
                continue
            if tok == "$" and doc_ccy and doc_ccy in DOLLAR_CURRENCIES:
                ccy = doc_ccy
            if _PAID_RE.search(line):
                # A payment label is not evidence that money was received. Keep
                # uncertain language out of amount_paid and require the existing
                # review flow before a draft can queue an external-payment record.
                # Match the complete statement, not a paid phrase embedded in
                # a condition, quotation, request or unsettled payment report.
                statement = re.sub(r"\s+", " ", line[:monies[0].start()] + "<M>" + line[monies[0].end():])
                if len(monies) == 1 and _PAID_CONFIRMED_RE.fullmatch(statement):
                    payments.append((ccy, amt))
                    try:
                        valid_payment = amt >= 0 and quantize(amt, ccy) == amt
                    except DecimalException:
                        valid_payment = False
                    if not valid_payment:
                        issues.append(Issue("amount_paid", "error", f"Prior payment {ccy} {amt} must be nonnegative and exactly representable in its currency; review it before drafting."))
                else:
                    issues.append(Issue("amount_paid", "error",
                                        f"Prior payment is not unambiguously confirmed; review the amount already received: {line!r}"))
                continue
            if _TOTAL_RE.search(line):
                stated.append((ccy, amt))
                continue
            item, reason = self._item_from_line(line, monies[0])
            if item is None:
                issues.append(Issue("line_items", "warning", f"Could not parse priced line: {line!r}"))
                continue
            item.currency = ccy or doc_ccy
            if tok == "$" and doc_ccy and doc_ccy in DOLLAR_CURRENCIES and doc_ccy != "USD":
                item.currency = doc_ccy
                issues.append(Issue(f"line_items[{len(items)}].currency", "warning", f"'$' interpreted as {doc_ccy} per the email."))
            if reason:
                sev = "error" if item.qty is None else "warning"
                issues.append(Issue(f"line_items[{len(items)}].qty", sev, reason))
            items.append(item)
        if payments:
            with localcontext() as ctx:
                ctx.prec = max(ctx.prec, max(len(amount.as_tuple().digits) for _, amount in payments)
                               + len(str(len(payments))) + 1)
                paid = sum((amount for _, amount in payments), Decimal(0))
            item_currencies = {item.currency for item in items}
            payment_currencies = {currency for currency, _ in payments}
            if len(item_currencies) != 1 or payment_currencies != item_currencies:
                issues.append(Issue("amount_paid", "error", f"Prior payment currencies {sorted(payment_currencies)} do not match a single item currency {sorted(item_currencies, key=str)}; assign payments manually without currency conversion."))
        return items, paid, stated, issues

    @staticmethod
    def _item_from_line(line: str, m: re.Match) -> tuple[Optional[LineItem], Optional[str]]:
        s = line[: m.start()] + "<M>" + line[m.end():]
        _, price, _ = parse_money(m)
        for pat in _ITEM_PATTERNS:
            pm = pat.search(s)
            if not pm:
                continue
            desc = pm.group("desc").strip().rstrip(" :–—-,")
            if not desc or len(desc.split()) > 12:
                continue
            gd = pm.groupdict()
            qty, reason = (Decimal(1), None) if gd.get("qty") is None else parse_qty(gd["qty"])
            unit = gd.get("unit")
            desc = desc[0].upper() + desc[1:]
            return LineItem(desc=desc, qty=qty, unit_price=price, unit=unit), reason
        return None, None

    @staticmethod
    def _table(lines: list[str], doc_ccy: Optional[str]):
        items: list[LineItem] = []
        consumed: set[int] = set()
        issues: list[Issue] = []
        totals: list[tuple[Optional[str], Decimal]] = []
        rows = [(i, [c.strip() for c in l.strip().strip("|").split("|")]) for i, l in enumerate(lines) if l.count("|") >= 2]
        header = None
        for i, cells in rows:
            low = [c.lower() for c in cells]
            if header is None:
                if any(c in ("qty", "quantity", "hours", "hrs") for c in low):
                    def col(*names):
                        return next((k for k, c in enumerate(low) if any(n in c for n in names)), None)
                    header = {
                        "desc": col("item", "description", "service", "task") or 0,
                        "qty": col("qty", "quantity", "hours", "hrs"),
                        "price": col("unit price", "price", "rate", "unit"),
                    }
                    consumed.add(i)
                continue
            consumed.add(i)
            if all(re.fullmatch(r":?-{2,}:?", c) for c in cells if c):
                continue
            try:
                desc = cells[header["desc"]]
                raw_price = cells[header["price"]] if header["price"] is not None else ""
                raw_qty = cells[header["qty"]] if header["qty"] is not None else "1"
            except IndexError:
                issues.append(Issue("line_items", "warning", f"Malformed table row: {lines[i].strip()!r}"))
                continue
            mm = MONEY_RE.search(raw_price)
            if mm:
                try:
                    ccy, price, tok = parse_money(mm)
                except ValueError as error:
                    issues.append(Issue("line_items", "error", f"Unreadable table amount ({error}): {raw_price!r}"))
                    continue
                if tok == "$" and doc_ccy and doc_ccy in DOLLAR_CURRENCIES and doc_ccy != "USD":
                    ccy = doc_ccy
            else:
                bare = re.fullmatch(_NUM, raw_price)
                if not bare:
                    issues.append(Issue("line_items", "error", f"No unambiguous price in table row: {lines[i].strip()!r}"))
                    continue
                try:
                    ccy, price = None, _dec(bare.group(0))
                except ValueError as error:
                    issues.append(Issue("line_items", "error", f"Unreadable table amount ({error}): {raw_price!r}"))
                    continue
            if _TOTAL_RE.search(desc):
                totals.append((ccy or doc_ccy, price))
                continue
            qty, reason = parse_qty(raw_qty)
            if reason:
                issues.append(Issue(f"line_items[{len(items)}].qty", "error" if qty is None else "warning", reason))
            items.append(LineItem(desc=desc, qty=qty, unit_price=price, currency=ccy or doc_ccy))
        return items, consumed, issues, totals


# ------------------------------------------------------------- LLM extractor

LLM_PROMPT = """You extract invoice data from a freelancer's job email.
Return ONLY a JSON object, no prose, matching:
{"client_name": string|null, "client_email": string|null, "currency": ISO-4217 string|null,
 "line_items": [{"desc": string, "qty": number|null, "unit_price": number, "currency": string|null}],
 "due_days": integer|null, "amount_paid": number, "confidence": number 0..1,
 "issues": [{"field": string, "severity": "error"|"warning"|"info", "message": string}]}
Rules: never invent an email address or price that is not in the text; use null and add an
issue instead. Quoted earlier messages (lines starting with '>') are history, not scope.
If a deposit/partial payment was already made, put it in amount_paid.

EMAIL:
<<<
{text}
>>>"""


def _strip_fence(s: str) -> str:
    s = s.strip()
    m = re.match(r"^```(?:json)?\s*(.*?)\s*```$", s, re.S)
    return m.group(1) if m else s


class LLMExtractor:
    """Model-agnostic: inject any `complete(prompt) -> str` (OpenAI, Anthropic, local...).

    Output is never trusted blindly: it goes through the same `validate()` as the rules
    extractor plus a grounding check (email must literally appear in the source text).
    """

    name = "llm"

    def __init__(self, complete: Callable[[str], str]):
        self.complete = complete

    def extract(self, text: str) -> Extraction:
        raw = self.complete(LLM_PROMPT.replace("{text}", text))
        try:
            data = json.loads(_strip_fence(raw))
            if not isinstance(data, dict):
                raise ValueError("not an object")
            model_issues = data.pop("issues", []) or []
            model_conf = float(data.pop("confidence", 0.5))
            ex = Extraction.from_dict(data)
            ex.issues = [Issue(**i) for i in model_issues if isinstance(i, dict) and {"field", "severity", "message"} <= set(i)]
        except (ValueError, TypeError, KeyError) as e:
            bad = Extraction(None, None, None, [], None, source=self.name,
                             issues=[Issue("*", "error", f"LLM output unusable: {e}")])
            bad.confidence = 0.0
            return bad
        ex.source = self.name
        if ex.client_email:
            ex.client_email = ex.client_email.lower()
        for li in ex.line_items:
            li.currency = li.currency or ex.currency
        if ex.currency is None and ex.currencies():
            ex.currency = Counter(li.currency for li in ex.line_items).most_common(1)[0][0]
        v = validate(ex, text)
        if any(i.field == "client_email" and "hallucination" in i.message for i in v):
            ex.client_email = None
        ex.issues += v
        ex.confidence = min(round(model_conf, 2), compute_confidence(ex.issues))
        return ex


class HybridExtractor:
    """Rules first (free, deterministic); LLM only when rules confidence < threshold."""

    name = "hybrid"

    def __init__(self, primary: Extractor, fallback: Optional[Extractor] = None, threshold: float = 0.75):
        self.primary, self.fallback, self.threshold = primary, fallback, threshold

    def extract(self, text: str) -> Extraction:
        first = self.primary.extract(text)
        if first.confidence >= self.threshold or self.fallback is None:
            return first
        second = self.fallback.extract(text)
        best, other = (second, first) if second.confidence > first.confidence else (first, second)
        best.issues.append(Issue("*", "info",
                                 f"Hybrid: chose {best.source} ({best.confidence}) over {other.source} ({other.confidence})."))
        if first.client_email and second.client_email and first.client_email != second.client_email:
            best.issues.append(Issue("client_email", "warning",
                                     f"Extractors disagree on email: {first.client_email} vs {second.client_email}."))
            best.confidence = compute_confidence(best.issues) if best.source == "rules" else min(best.confidence, compute_confidence(best.issues))
        return best


def split_by_currency(ex: Extraction) -> list[Extraction]:
    """One Extraction per currency (PayPal invoices carry a single currency_code)."""
    ccys = ex.currencies()
    if len(ccys) <= 1:
        return [ex]
    parts = []
    for c in ccys:
        parts.append(Extraction(
            ex.client_name, ex.client_email, c,
            [li for li in ex.line_items if li.currency == c], ex.due_days,
            Decimal(0), [i for i in ex.issues if i.field != "currency"], ex.confidence, ex.source,
        ))
    return parts

"""PayPal Invoicing v2 client interface + an offline `SandboxMock`.

Nothing in this module talks to the network unless you construct `HttpPayPalClient`
yourself AND set LEDGERLY_ALLOW_NETWORK=1. Tests and the demo only use `SandboxMock`.

Shapes below were written from the PayPal developer docs (field names, enums, status
codes). Where I was not certain of an exact detail it is marked "ASSUMPTION" - verify
against the sandbox before relying on it.

Docs used:
  Invoicing v2 API reference ........ https://developer.paypal.com/docs/api/invoicing/v2/
    - Create draft invoice  POST /v2/invoicing/invoices
    - Send invoice          POST /v2/invoicing/invoices/{invoice_id}/send
    - Send reminder         POST /v2/invoicing/invoices/{invoice_id}/remind
    - Show invoice details  GET  /v2/invoicing/invoices/{invoice_id}
    - Record payment        POST /v2/invoicing/invoices/{invoice_id}/payments
    - Generate inv. number  POST /v2/invoicing/generate-next-invoice-number
  Invoicing integration guide ....... https://developer.paypal.com/docs/invoicing/
  Webhooks overview ................. https://developer.paypal.com/api/rest/webhooks/
  Webhook event names (INVOICING.*) . https://developer.paypal.com/api/rest/webhooks/event-names/
  Verify webhook signature .......... https://developer.paypal.com/docs/api/webhooks/v1/#verify-webhook-signature_post
  OAuth 2.0 access token ............ https://developer.paypal.com/api/rest/authentication/
  Sandbox base URL / environments ... https://developer.paypal.com/api/rest/sandbox/
  Currency codes .................... https://developer.paypal.com/api/rest/reference/currency-codes/
  Error response format ............. https://developer.paypal.com/api/rest/responses/
"""
